  TextBlock SectionTitle(string text){return new TextBlock{Text=text,FontSize=19,FontWeight=FontWeights.SemiBold,Foreground=Ink,Margin=new Thickness(0,0,0,10)};}
  TextBlock Paragraph(string text){return new TextBlock{Text=text,FontSize=13,Foreground=Muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,11)};}
  Border InfoCard(string title,string text){var stack=new StackPanel();stack.Children.Add(new TextBlock{Text=title,FontSize=11,Foreground=Muted});stack.Children.Add(new TextBlock{Text=string.IsNullOrWhiteSpace(text)?"Not reported":text,FontSize=12,Foreground=Ink,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,5,0,0)});return new Border{Background=Raised,BorderBrush=Line,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(8),Padding=new Thickness(12),Margin=new Thickness(0,0,8,8),Child=stack};}
  string UpdatedText(FoundGame game){return game==null||string.IsNullOrWhiteSpace(game.LastUpdated)?"Not reported by "+(game==null?"the launcher":game.Source):game.LastUpdated+(game.Source=="Steam"?" (Steam)":"");}
  void OpenDetails(FoundGame game){selectedGame=game;modalVersion++;int version=modalVersion;modalTitle.Text=game.Name;modalMeta.Text=game.Source+"   ·   "+(game.Source=="Steam"?"Steam library":"Installed game");modalUpdated.Text="Last Updated  ·  "+UpdatedText(game);modalOverviewText="Looking up the game overview…";modalImage.Source=null;ShowModalTab("Overview");pageScroll.Effect=new BlurEffect{Radius=7,KernelType=KernelType.Gaussian};modalFrame.Width=Math.Min(850,Math.Max(360,ActualWidth-44));modalFrame.Height=Math.Min(620,Math.Max(320,ActualHeight-44));modalOverlay.Visibility=Visibility.Visible;LoadModalArt(game,version);LoadModalSummary(game,version);}
  void CloseDetails(){modalVersion++;selectedGame=null;modalOverlay.Visibility=Visibility.Collapsed;pageScroll.Effect=null;}
  async void LoadModalArt(FoundGame game,int version){try{string path=await SteamArtwork.GetLibraryImageAsync(game,cancel.Token).ConfigureAwait(false);if(path==null||cancel.IsCancellationRequested)return;await Dispatcher.InvokeAsync(delegate{if(version!=modalVersion||modalOverlay.Visibility!=Visibility.Visible)return;try{var bmp=new BitmapImage();bmp.BeginInit();bmp.CacheOption=BitmapCacheOption.OnLoad;bmp.UriSource=new Uri(path,UriKind.Absolute);bmp.EndInit();bmp.Freeze();modalImage.Source=bmp;}catch{}});}catch{}}
  async void LoadModalSummary(FoundGame game,int version){try{var overview=await SteamArtwork.GetStoreOverviewAsync(game,cancel.Token);if(version!=modalVersion||modalOverlay.Visibility!=Visibility.Visible)return;if(overview!=null&&!string.IsNullOrWhiteSpace(overview.Summary)){modalOverviewText=overview.Summary;if(!string.IsNullOrWhiteSpace(overview.ReleaseDate))modalUpdated.Text+="   ·   Released "+overview.ReleaseDate;}else modalOverviewText=LocalOverview(game);if(modalSummary!=null)modalSummary.Text=modalOverviewText;}catch{if(version==modalVersion){modalOverviewText=LocalOverview(game);if(modalSummary!=null)modalSummary.Text=modalOverviewText;}}}
  string LocalOverview(FoundGame game){string name=(game.Name??"").ToLowerInvariant();if(name.Contains("beamng"))return "BeamNG.drive is a realistic, immersive driving game with soft-body physics, detailed vehicles, and a large open world.";if(name.Contains("valorant"))return "VALORANT is a team-based tactical shooter from Riot Games, combining precise gunplay with agent abilities.";if(name.Contains("fortnite"))return "Fortnite is an online game from Epic Games with Battle Royale, creative experiences, and other game modes.";return "This game was discovered in your "+game.Source+" library. FramePilot found its installation folder and launch route on this PC.";}
  string libraryKey; void Refresh(){if(cancel.IsCancellationRequested)return;games=app.WpfGames??new FoundGame[0];if(totalGamesValue!=null)totalGamesValue.Text=games.Length.ToString();string status=app.WpfGameScanStatus;if(!string.IsNullOrWhiteSpace(status))scanText.Text=status;RefreshFilters();string next=string.Join("|",games.Select(x=>x.Source+":"+x.AppId+":"+x.Name+":"+x.Folder+":"+x.Launch+":"+x.LastUpdated));if(libraryKey!=next){libraryKey=next;Render();}}
  void RefreshFilters(){foreach(var pair in filterButtons){bool selected=pair.Key==source;pair.Value.Background=selected?new SolidColorBrush(Color.FromRgb(54,38,25)):Panel;pair.Value.BorderBrush=selected?Accent:Line;pair.Value.Foreground=selected?Brushes.White:Ink;}}
  void Render(){if(cancel.IsCancellationRequested)return;IEnumerable<FoundGame> shown=games;if(source=="Steam")shown=shown.Where(x=>x.Source=="Steam");else if(source=="Epic Games"||source=="GOG")shown=shown.Where(x=>x.Source==source);else if(source=="Other")shown=shown.Where(x=>x.Source!="Steam"&&x.Source!="Epic Games"&&x.Source!="GOG");if(!string.IsNullOrWhiteSpace(query))shown=shown.Where(x=>x.Name.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0);shown=sort.SelectedIndex==1?shown.OrderBy(x=>x.Source).ThenBy(x=>x.Name):shown.OrderBy(x=>x.Name);FoundGame[] visible=shown.ToArray();cardGrid.Children.Clear();cardGrid.Columns=listMode?1:CardColumns();cardGrid.Rows=Math.Max(1,(int)Math.Ceiling((double)visible.Length/cardGrid.Columns));foreach(var game in visible)cardGrid.Children.Add(Card(game));if(visible.Length==0){var empty=new TextBlock{Text=games.Length==0?"No games discovered yet. Use the menu above to scan installed libraries or add a game.":"No games match this search.",Foreground=Muted,FontSize=13,Margin=new Thickness(8),TextWrapping=TextWrapping.Wrap};cardGrid.Children.Add(empty);}count.Text=visible.Length+" games shown";}
  int CardColumns(){double width=ActualWidth;if(width<850)return 2;if(width<1150)return 3;if(width<1400)return 4;return 5;}
  void ResizeCards(){if(cardGrid.Children.Count>0)cardGrid.Columns=listMode?1:CardColumns();}
  UIElement Card(FoundGame game){var outer=new Border{Background=Panel,BorderBrush=Line,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(11),Margin=new Thickness(0,0,10,12),ClipToBounds=true,ToolTip="View game overview, performance options, and files"};var stack=new StackPanel();var art=new Grid{Height=listMode?110:100,ClipToBounds=true,Background=Raised};var image=new Image{Stretch=Stretch.UniformToFill,Visibility=Visibility.Collapsed};art.Children.Add(image);var place=new Border{Background=new LinearGradientBrush(new GradientStopCollection{new GradientStop(Color.FromRgb(69,48,31),0),new GradientStop(Color.FromRgb(23,20,18),1)})};place.Child=new TextBlock{Text=game.Name,Foreground=Ink,FontSize=18,FontWeight=FontWeights.SemiBold,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(14),TextTrimming=TextTrimming.CharacterEllipsis};art.Children.Add(place);LoadArt(game,image,place);var menuButton=MakeButton("⋮");menuButton.Width=30;menuButton.Height=30;menuButton.Padding=new Thickness(0);menuButton.HorizontalAlignment=HorizontalAlignment.Right;menuButton.VerticalAlignment=VerticalAlignment.Top;menuButton.Margin=new Thickness(0,7,7,0);var menu=new ContextMenu();AddMenu(menu,"Game overview",delegate{OpenDetails(game);});AddMenu(menu,"Settings and presets",delegate{app.WpfOpenGameProfile(game);});AddMenu(menu,"Launch",delegate{app.WpfLaunchGame(game);});AddMenu(menu,"Open game folder",delegate{app.WpfOpenGameFolder(game);});if(game.Source=="Custom")AddMenu(menu,"Remove custom link",delegate{app.WpfRemoveCustomGame(game);});menuButton.ContextMenu=menu;menuButton.Click+=delegate{menu.IsOpen=true;};art.Children.Add(menuButton);stack.Children.Add(art);
   var info=new StackPanel{Margin=new Thickness(11,8,10,10)};var titleRow=new DockPanel();var dot=new Ellipse{Width=8,Height=8,Fill=Good,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(7,0,0,0)};DockPanel.SetDock(dot,Dock.Right);titleRow.Children.Add(dot);titleRow.Children.Add(new TextBlock{Text=game.Name,FontSize=13,FontWeight=FontWeights.SemiBold,Foreground=Ink,TextTrimming=TextTrimming.CharacterEllipsis,VerticalAlignment=VerticalAlignment.Center});info.Children.Add(titleRow);info.Children.Add(new TextBlock{Text="◉   "+game.Source,FontSize=11,Foreground=Muted,Margin=new Thickness(0,4,0,0)});info.Children.Add(new TextBlock{Text="Installed  ·  Playtime not tracked",FontSize=10,Foreground=Muted,Margin=new Thickness(0,4,0,0)});stack.Children.Add(info);outer.Child=stack;outer.MouseLeftButtonUp+=delegate(object sender,MouseButtonEventArgs e){if(menuButton.IsMouseOver)return;OpenDetails(game);e.Handled=true;};AutomationProperties.SetName(outer,"Open game overview for "+game.Name);return outer;}
  async void LoadArt(FoundGame game,Image image,Border placeholder){try{var cached=ArtworkImages.Peek(game);if(cached!=null){image.Source=cached;image.Visibility=Visibility.Visible;placeholder.Visibility=Visibility.Collapsed;return;}var bitmap=await ArtworkImages.GetAsync(game,cancel.Token);if(bitmap==null||cancel.IsCancellationRequested)return;image.Source=bitmap;image.Visibility=Visibility.Visible;placeholder.Visibility=Visibility.Collapsed;}catch{}}
  async Task RunScan(bool folder){try{scanText.Text=folder?"Choose a folder to scan for EXE candidates…":"Scanning installed game libraries…";await app.WpfScanGames(folder);Refresh();}catch(Exception e){MessageBox.Show("The game scan could not finish: "+e.GetBaseException().Message,"FramePilot",MessageBoxButton.OK,MessageBoxImage.Information);}}
  void ShowIssues(){var issues=app.WpfGameScanIssues;MessageBox.Show(issues.Length==0?"No scan issues reported.":string.Join("\r\n",issues),"Game scan details",MessageBoxButton.OK,MessageBoxImage.Information);}
  void ShowKeyDialog(){var dialog=new Window{Title="SteamGridDB artwork settings",Width=460,Height=200,WindowStartupLocation=WindowStartupLocation.CenterOwner,Owner=Window.GetWindow(this),Background=Bg,ResizeMode=ResizeMode.NoResize};var panel=new StackPanel{Margin=new Thickness(20)};panel.Children.Add(new TextBlock{Text="SteamGridDB API key",Foreground=Ink,FontSize=17,FontWeight=FontWeights.SemiBold});panel.Children.Add(new TextBlock{Text="Optional. Stored encrypted for this Windows account. Leave blank to clear the saved key.",Foreground=Muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,12)});var box=new PasswordBox{Background=Raised,Foreground=Ink,BorderBrush=Line,Height=34,Padding=new Thickness(8)};panel.Children.Add(box);var save=MakeButton("Save key");save.Margin=new Thickness(0,12,0,0);save.HorizontalAlignment=HorizontalAlignment.Right;save.Click+=delegate{app.WpfSaveArtworkKey(box.Password);dialog.Close();};panel.Children.Add(save);dialog.Content=panel;dialog.ShowDialog();}
  void Try(Action action){try{action();}catch(Exception e){MessageBox.Show(e.GetBaseException().Message,"FramePilot",MessageBoxButton.OK,MessageBoxImage.Information);}}
  public void Dispose(){app.WpfChanged-=Refresh;cancel.Cancel();cancel.Dispose();}
 }
